using MediatR;using TopLab.Application.Common.Interfaces;using TopLab.Application.Common.Results;using TopLab.Domain.Results;
namespace TopLab.Application.Features.CultureResults.Commands.UnverifyCultureResult;
public sealed class UnverifyCultureResultCommandHandler:IRequestHandler<UnverifyCultureResultCommand,Result>{private readonly IApplicationDbContext _db;public UnverifyCultureResultCommandHandler(IApplicationDbContext db)=>_db=db;public async Task<Result> Handle(UnverifyCultureResultCommand r,CancellationToken ct){var pt=_db.Set<PatientTest>().FirstOrDefault(x=>x.Id.Value==r.PatientTestId);if(pt is null)return Result.Failure(Error.NotFound("التحليل غير موجود"));if(pt.IsPrinted||pt.IsDelivered)return Result.Failure(Error.Conflict("لا يمكن إلغاء اعتماد نتيجة مزرعة مطبوعة أو مسلمة."));try{pt.Unreview();}catch(InvalidOperationException e){return Result.Failure(Error.Conflict(e.Message));}await _db.SaveChangesAsync(ct);return Result.Success();}}
